typedef unsigned int u_int;

class MenuSystem;
class MenuEntry;
typedef MenuEntry *pMenuEntry;

class Menu
{
	Menu       *parent;
	int         entries;
	pMenuEntry *entry;
	int         activeentry;
	bool        isopen;
	Menu       *closeto;
	MenuSystem *control;

public:
	virtual ~Menu();
	virtual void CloseAll( void );
	virtual void OnTick( float dtime );
	virtual void OnButtonPress( int buttonid );
	virtual void OnButtonRelease( int buttonid );
	virtual void OnOpen( Menu *cto, MenuSystem *c );
	virtual void OnClose( bool toparent );
};

class MenuEntityDraw : public Menu
{
public:
	virtual void OnOpen(Menu *cto, MenuSystem *c);
};

class MenuParticleDraw : public Menu
{
public:
	virtual void OnOpen(Menu *cto, MenuSystem *c);
};

class MenuWaterDraw : public Menu
{
public:
	virtual void OnOpen(Menu *cto, MenuSystem *c);
};

enum MenudrawTypeEnum
{
	MENUDRAW_TypeIGO,
	MENUDRAW_TypeShadow,
	MENUDRAW_TypeMax
};

extern int MENUDRAW_Flags[MENUDRAW_TypeMax];
extern bool (*MENUDRAW_Get[MENUDRAW_TypeMax])(void);
extern MenuEntityDraw *MENUDRAW_MenuEntities;
extern MenuParticleDraw *MENUDRAW_MenuParticle;
extern MenuWaterDraw *MENUDRAW_MenuWater;

__asm__(".equ MENUDRAW_Flags, 0x0058A438");
__asm__(".equ MENUDRAW_Get, 0x0046B258");
__asm__(".equ MENUDRAW_MenuEntities, 0x0046B19C");
__asm__(".equ MENUDRAW_MenuParticle, 0x0046B208");
__asm__(".equ MENUDRAW_MenuWater, 0x0046B240");
__asm__(".equ OnOpen__4MenuP4MenuP10MenuSystem, 0x0023EAE0");

class MenuDraw : public Menu
{
public:
	virtual void OnOpen(Menu *cto, MenuSystem *c) __asm__("OnOpen__8MenuDrawP4MenuP10MenuSystem");
};

void MenuDraw::OnOpen(Menu *cto, MenuSystem *c)
{
	for (u_int i = 0; i < MENUDRAW_TypeMax; ++i)
	{
		MENUDRAW_Flags[i] = MENUDRAW_Get[i]();
	}
	// For "All On" and "All Off" to be recursive.
	// A little wasteful, since these will be called again
	// when the submenus are activated.  Also, this temporarily
	// sets the parent of these menus incorrectly. (dc 10/18/01)
	MENUDRAW_MenuEntities->OnOpen(cto, c);
	MENUDRAW_MenuParticle->OnOpen(cto, c);
	MENUDRAW_MenuWater->OnOpen(cto, c);

	Menu::OnOpen(cto, c);
}
